/**
 * Client-side site search over `public/search-index.json`
 * (generated by `pnpm search:index`, see scripts/generate-search-index.mjs).
 *
 * Results are whole pages, ranked by relevance. A page only carries content
 * snippets when its content actually matches the query.
 */

const INDEX_URL = '/search-index.json'

const MAX_PAGE_RESULTS = 8
const MAX_SNIPPETS_PER_PAGE = 3
const MAX_PROFILE_RESULTS = 5
/** Results scoring below this fraction of the top result are hidden. */
const MIN_RELATIVE_SCORE = 0.05

/** Field weights: how much a full match in each field contributes. */
const WEIGHTS = {
  title: 10,
  heading: 9,
  path: 7,
  keyword: 6,
  description: 3,
  contentHeading: 4,
  contentText: 2.5,
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

/** Lowercase, strip diacritics (ü -> u, ß -> ss) so "uber" finds "Über". */
export function normalize(value) {
  return String(value ?? '')
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/ß/g, 'ss')
    .toLowerCase()
}

export function tokenize(value) {
  return normalize(value)
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean)
}

/** True when `a` and `b` differ by at most one edit (insert, delete, replace, swap). */
function withinOneEdit(a, b) {
  if (Math.abs(a.length - b.length) > 1) return false

  let i = 0
  let j = 0
  let edits = 0

  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i++
      j++
      continue
    }
    if (++edits > 1) return false
    if (a.length === b.length && a[i] === b[j + 1] && a[i + 1] === b[j]) {
      i += 2 // transposition ("abuot" -> "about")
      j += 2
    } else if (a.length > b.length) i++
    else if (a.length < b.length) j++
    else {
      i++
      j++
    }
  }

  return edits + (a.length - i) + (b.length - j) <= 1
}

/** 0..1 — how well a single query token matches a list of words. */
function matchToken(token, words) {
  let best = 0

  for (const word of words) {
    if (word === token) return 1

    if (word.startsWith(token)) {
      best = Math.max(best, token.length >= 3 ? 0.8 : 0.5)
    } else if (token.length >= 3 && word.includes(token)) {
      best = Math.max(best, 0.45)
    } else if (token.length >= 4 && withinOneEdit(word, token)) {
      best = Math.max(best, 0.35) // typo tolerance
    }
  }

  return best
}

/**
 * Scores one field against the query.
 * Returns `{ score: 0..~2, matched: boolean[] }` (one flag per query token).
 */
function scoreField(query, text) {
  const matched = query.tokens.map(() => false)
  if (!text) return { score: 0, matched }

  const normalizedText = normalize(text)
  const words = tokenize(text)
  let sum = 0

  query.tokens.forEach((token, index) => {
    const value = matchToken(token, words)
    if (value > 0) {
      matched[index] = true
      sum += value
    }
  })

  let score = sum / query.tokens.length

  // Bonus for the whole phrase appearing, and for an exact field match.
  if (score > 0 && query.tokens.length > 1 && normalizedText.includes(query.phrase)) score += 0.5
  if (score > 0 && normalizedText.trim() === query.phrase) score += 0.5

  return { score, matched }
}

function mergeMatched(target, source) {
  source.forEach((value, index) => {
    if (value) target[index] = true
  })
}

/** Text of a localized `{ en, de, … }` object in the current language (falls back to English). */
export function localized(text, language, fallback = 'en') {
  if (!text) return ''
  if (typeof text === 'string') return text
  return text[language] ?? text[language?.split('-')[0]] ?? text[fallback] ?? Object.values(text)[0] ?? ''
}

/** Current language plus English, so searching in English always works. */
function searchableText(text, language, fallback) {
  const primary = localized(text, language, fallback)
  const english = localized(text, fallback, fallback)
  return primary === english ? primary : `${primary} ${english}`
}

export function parseQuery(input) {
  const tokens = tokenize(input)
  return { raw: input, tokens, phrase: tokens.join(' ') }
}

/**
 * Splits `text` into `{ text, match }` parts so matching words can be
 * wrapped in `<mark>`. Works on whole words, so diacritics are no problem.
 */
export function highlightParts(text, tokens) {
  if (!text || !tokens?.length) return [{ text, match: false }]

  return text
    .split(/([\p{L}\p{N}]+)/u)
    .filter(Boolean)
    .map((part) => {
      const word = normalize(part)
      const match =
        /[\p{L}\p{N}]/u.test(part) &&
        tokens.some((token) => word.startsWith(token) || (token.length >= 3 && word.includes(token)))
      return { text: part, match }
    })
}

// ---------------------------------------------------------------------------
// Index loading
// ---------------------------------------------------------------------------

let indexPromise = null

export function loadSearchIndex() {
  indexPromise ??= fetch(INDEX_URL, { cache: 'no-cache' })
    .then((response) => {
      if (!response.ok) throw new Error(`Search index request failed (${response.status})`)
      return response.json()
    })
    .catch((error) => {
      indexPromise = null // allow a retry on next focus
      throw error
    })

  return indexPromise
}

// ---------------------------------------------------------------------------
// Page search
// ---------------------------------------------------------------------------

/**
 * Searches the page index.
 *
 * @returns {Array<{
 *   id: string, path: string, aliases: string[], title: string,
 *   description: string, score: number,
 *   matches: Array<{ id: string, type: string, text: string, source: string, score: number }>
 * }>}
 */
export function searchPages(index, input, language) {
  const query = typeof input === 'string' ? parseQuery(input) : input
  if (!index?.pages || !query.tokens.length) return []

  const fallback = index.defaultLanguage ?? 'en'
  const results = []

  for (const page of index.pages) {
    const matched = query.tokens.map(() => false)
    let score = 0

    const addField = (text, weight) => {
      const field = scoreField(query, text)
      mergeMatched(matched, field.matched)
      score += field.score * weight
    }

    addField(page.title, WEIGHTS.title)
    addField(searchableText(page.heading, language, fallback), WEIGHTS.heading)
    addField([page.path, ...(page.aliases ?? [])].join(' '), WEIGHTS.path)
    addField(page.description, WEIGHTS.description)

    // Keywords: only the best keyword counts, so long lists don't dominate.
    let bestKeyword = 0
    for (const keyword of page.keywords ?? []) {
      const field = scoreField(query, keyword)
      mergeMatched(matched, field.matched)
      bestKeyword = Math.max(bestKeyword, field.score)
    }
    score += bestKeyword * WEIGHTS.keyword

    // Content: rank entries, add the best few with diminishing returns.
    const contentMatches = []
    for (const item of page.content ?? []) {
      const field = scoreField(query, searchableText(item.text, language, fallback))
      if (field.score <= 0) continue

      mergeMatched(matched, field.matched)
      const weight = item.type === 'heading' ? WEIGHTS.contentHeading : WEIGHTS.contentText
      // Content that appears on several pages (shared cards) is less specific.
      const itemScore = (field.score * weight) / Math.sqrt(item.shared ?? 1)

      contentMatches.push({
        id: item.id,
        type: item.type,
        text: localized(item.text, language, fallback),
        source: item.source,
        shared: item.shared ?? 1,
        rawScore: field.score,
        score: itemScore,
      })
    }

    contentMatches.sort((a, b) => b.score - a.score)
    contentMatches.slice(0, 3).forEach((item, position) => {
      score += item.score / 2 ** position
    })

    // Coverage: how many query words were found anywhere on the page.
    const coverage = matched.filter(Boolean).length / query.tokens.length
    if (coverage === 0) continue
    if (query.tokens.length > 1 && coverage < 0.5) continue
    score *= coverage ** 2

    // Only surface content that is genuinely relevant: decent matches that are
    // close to the page's best content hit.
    const bestContent = contentMatches[0]?.score ?? 0
    const matches = contentMatches
      .filter((item) => item.rawScore >= 0.45 && item.score >= bestContent * 0.6)
      .slice(0, MAX_SNIPPETS_PER_PAGE)
      .map((item) => ({
        id: item.id,
        type: item.type,
        text: item.text,
        source: item.source,
        shared: item.shared,
        score: item.score,
      }))

    results.push({
      id: page.id,
      path: page.path,
      aliases: page.aliases ?? [],
      title: page.title,
      description: page.description,
      score,
      matches,
    })
  }

  results.sort((a, b) => b.score - a.score || a.path.length - b.path.length)

  // Drop stragglers that are barely relevant compared to the best hit.
  const cutoff = (results[0]?.score ?? 0) * MIN_RELATIVE_SCORE
  const visible = results.filter((result) => result.score >= cutoff).slice(0, MAX_PAGE_RESULTS)

  // Shared content (e.g. the About teaser card on several pages) is only shown
  // as a snippet under the best-ranked page that contains it.
  const shownShared = new Set()
  for (const result of visible) {
    result.matches = result.matches.filter((match) => {
      if (match.shared <= 1) return true
      if (shownShared.has(match.id)) return false
      shownShared.add(match.id)
      return true
    })
  }

  return visible
}

// ---------------------------------------------------------------------------
// Profile search (placeholder)
// ---------------------------------------------------------------------------

/**
 * PLACEHOLDER: static profile list until a real profile search exists.
 *
 * To make this real, replace the body of `searchProfiles` with a request to a
 * backend endpoint, e.g. `fetch(`/api/profiles/search?q=${encodeURIComponent(q)}`)`
 * on the discord-profile service, and map the response to the same shape.
 */
const PLACEHOLDER_PROFILES = [
  {
    id: 'profile:mrkoby07',
    name: 'MrKoby07',
    handle: 'master3307',
    description: 'Korbi · Developer & owner of this site',
    path: '/card',
    keywords: ['korbi', 'koby', 'owner', 'developer', 'admin'],
  },
]

/**
 * @returns {Promise<Array<{ id, name, handle, description, path, score, placeholder: true }>>}
 */
export async function searchProfiles(input, { signal } = {}) {
  const query = typeof input === 'string' ? parseQuery(input) : input
  if (!query.tokens.length || signal?.aborted) return []

  return PLACEHOLDER_PROFILES.map((profile) => {
    const name = scoreField(query, `${profile.name} ${profile.handle}`)
    const keywords = scoreField(query, profile.keywords.join(' '))
    const description = scoreField(query, profile.description)
    const score = name.score * 3 + keywords.score * 2 + description.score

    return { ...profile, score, placeholder: true }
  })
    .filter((profile) => profile.score >= 0.8)
    .sort((a, b) => b.score - a.score)
    .slice(0, MAX_PROFILE_RESULTS)
}
